<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Spiral Galaxy</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: #000;
  }
  canvas {
    display: block;
    width: 100vw;
    height: 100vh;
  }
</style>
</head>
<body>
<canvas id="galaxy"></canvas>
<script>
(function () {
  const canvas = document.getElementById('galaxy');
  const ctx = canvas.getContext('2d');

  let W, H, CX, CY;

  function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
    CX = W / 2;
    CY = H / 2;
  }
  window.addEventListener('resize', resize);
  resize();

  // ----- Galaxy parameters -----
  const NUM_STARS = 700;
  const TWO_PI = Math.PI * 2;
  const ARMS = 2;              // number of spiral arms
  const ARM_TWIST = 2.4;       // how tightly the arms wrap

  // ----- Star generation -----
  // Each star: base radius, base angle, angular speed, size, color, twinkle phase
  const stars = [];

  function rand(min, max) {
    return min + Math.random() * (max - min);
  }

  function makeColor(t) {
    // t in [0,1]: 0 = warm core (yellow/white), 1 = cool outer (blue/white)
    // Interpolate through warm white -> pale yellow -> pale blue
    const r = Math.round(255 - t * 90);
    const g = Math.round(245 - t * 40);
    const b = Math.round(210 + t * 45);
    return 'rgb(' + r + ',' + g + ',' + b + ')';
  }

  for (let i = 0; i < NUM_STARS; i++) {
    // Bias distribution toward the core with a power curve
    const t = Math.pow(Math.random(), 1.7);       // 0 = core, 1 = edge
    const maxR = Math.min(W, H) * 0.46;
    const baseR = 18 + t * (maxR - 18);

    // Spiral arm placement: angle follows logarithmic spiral + scatter
    const armIndex = i % ARMS;
    const armOffset = (TWO_PI / ARMS) * armIndex;
    const spiralAngle = Math.log(baseR / 18 + 1) * ARM_TWIST;
    const scatter = (Math.random() - 0.5) * (0.5 + t * 0.9);
    const baseAngle = armOffset + spiralAngle + scatter;

    // Inner stars orbit faster (roughly flat-ish rotation curve, slightly falling)
    const speed = 0.0022 / Math.sqrt(baseR / 60);

    stars.push({
      r: baseR,
      angle: baseAngle,
      speed: speed,
      size: rand(0.4, 1.6) * (t < 0.25 ? 1.2 : 1),
      color: makeColor(t + rand(-0.15, 0.15)),
      twinklePhase: Math.random() * TWO_PI,
      twinkleSpeed: rand(0.5, 2.5),
      twinkleAmp: rand(0.15, 0.5)
    });
  }

  // ----- Core glow (pre-rendered radial gradient) -----
  const glowCanvas = document.createElement('canvas');
  const glowSize = 512;
  glowCanvas.width = glowCanvas.height = glowSize;
  const gctx = glowCanvas.getContext('2d');
  const grad = gctx.createRadialGradient(
    glowSize / 2, glowSize / 2, 0,
    glowSize / 2, glowSize / 2, glowSize / 2
  );
  grad.addColorStop(0.00, 'rgba(255, 250, 235, 1)');
  grad.addColorStop(0.12, 'rgba(255, 240, 200, 0.85)');
  grad.addColorStop(0.30, 'rgba(255, 220, 160, 0.35)');
  grad.addColorStop(0.60, 'rgba(200, 180, 255, 0.08)');
  grad.addColorStop(1.00, 'rgba(0, 0, 0, 0)');
  gctx.fillStyle = grad;
  gctx.fillRect(0, 0, glowSize, glowSize);

  // ----- Faint background dust stars -----
  const bgStars = [];
  for (let i = 0; i < 120; i++) {
    bgStars.push({
      x: Math.random(),
      y: Math.random(),
      size: rand(0.3, 0.9),
      phase: Math.random() * TWO_PI,
      speed: rand(0.3, 1.2)
    });
  }

  // ----- Animation loop -----
  let lastTime = performance.now();

  function frame(now) {
    const dt = Math.min((now - lastTime) / 16.67, 3); // normalized to ~60fps steps
    lastTime = now;
    const time = now / 1000;

    // Clear with slight fade for subtle motion trails
    ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
    ctx.fillRect(0, 0, W, H);

    // Background dust stars
    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    for (let i = 0; i < bgStars.length; i++) {
      const s = bgStars[i];
      const tw = 0.4 + 0.6 * (0.5 + 0.5 * Math.sin(time * s.speed + s.phase));
      ctx.globalAlpha = tw * 0.5;
      ctx.beginPath();
      ctx.arc(s.x * W, s.y * H, s.size, 0, TWO_PI);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Core glow (gentle pulse)
    const pulse = 1 + 0.04 * Math.sin(time * 0.8);
    const glowR = Math.min(W, H) * 0.42 * pulse;
    ctx.drawImage(glowCanvas, CX - glowR, CY - glowR, glowR * 2, glowR * 2);

    // Orbiting stars
    for (let i = 0; i < stars.length; i++) {
      const s = stars[i];
      s.angle += s.speed * dt;

      const x = CX + Math.cos(s.angle) * s.r;
      const y = CY + Math.sin(s.angle) * s.r * 0.55; // slight elliptical tilt for depth

      const tw = 1 - s.twinkleAmp * (0.5 + 0.5 * Math.sin(time * s.twinkleSpeed + s.twinklePhase));

      ctx.globalAlpha = Math.max(0.15, Math.min(1, tw));
      ctx.fillStyle = s.color;
      ctx.beginPath();
      ctx.arc(x, y, s.size, 0, TWO_PI);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
